import { Cart, Category, ErrorEvent, Identity, PartyIdentification } from '../events';
/**
Description: Checkout step in which the shopper registers for a user id.
*/
export type CheckoutRegister = {
    events: Array<Cart | Identity | PartyIdentification | ErrorEvent>;
}

export class CheckoutRegisterBuilder {

    private checkoutRegister: CheckoutRegister = {
        events: []
    }

    private cart!: Cart;
    private errorEvent!: ErrorEvent;
    private identity!: Identity;
    private partyIdentification!: PartyIdentification;

    public withCart(cart: Cart) : CheckoutRegisterBuilder {
        this.cart = cart;
        return this;
    }
    public withErrorEvent(errorEvent: ErrorEvent) : CheckoutRegisterBuilder {
        this.errorEvent = errorEvent;
        return this;
    }
    public withIdentity(identity: Identity) : CheckoutRegisterBuilder {
        this.identity = identity;
        return this;
    }
    public withPartyIdentification(partyIdentification: PartyIdentification) : CheckoutRegisterBuilder {
        this.partyIdentification = partyIdentification;
        return this;
    }

    public build() : CheckoutRegister {
        if(this.cart) {
            this.checkoutRegister.events.push(this.cart);
        }
        if(this.errorEvent) {
            this.checkoutRegister.events.push(this.errorEvent);
        }
        if(this.identity) {
            this.checkoutRegister.events.push(this.identity);
        }
        if(this.partyIdentification) {
            this.checkoutRegister.events.push(this.partyIdentification);
        }

        return this.checkoutRegister;
    }
}
